import{_ as e,a,c as t}from"./chunks/framework.BkXmWmgX.js";const f=JSON.parse('{"title":"실용적인 프레임워크 사용 가이드 | OTW for FE","titleTemplate":false,"description":"","frontmatter":{"layout":"post","title":"OTW for FE","titleTemplate":false,"lang":"ko"},"headers":[],"params":{"id":"232e548d-8a8e-80b9-9a03-c5b9f894fa41","title":"실용적인 프레임워크 사용 가이드","date":"2025-07-23","coverUrl":"/kudzu-based-bench/assets/notion/7f480d976e3a7bc2.png","html":"<h1 data-notion-block-id=\\"232e548d-8a8e-80f9-bead-ca58456b191d\\">Beyond the Article: 한 걸음 더</h1><h2 data-notion-block-id=\\"235e548d-8a8e-8023-a626-cfe4f3a8e6d4\\" id=\\"235e548d-8a8e-8023-a626-cfe4f3a8e6d4\\">실용적인 프레임워크 사용 가이드</h2><a href=\\"https://www.lorenstew.art/blog/always-architect-with-contraints\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.lorenstew.art/blog/always-architect-with-contraints</a><p data-notion-block-id=\\"235e548d-8a8e-8046-827d-c1ebf2063d86\\">무조건 익숙한 프레임워크를 사용하기보다, 자신이 구현하려는 제약조건이 무엇인지 깨닫고 프레임워크를 선택하는 것이 좋은 아키텍쳐로 나아가는 방법이라고 제안하는 글입니다. 모든 프레임워크를 그대로 따르는 것보다는 프레임워크를 비판적으로 생각하고 선택하라는 것이죠. 물론 제약사항에 <a href=\\"https://ones-to-watch.ethansup.net/news/post/16be548d-8a8e-8042-ae4b-ff077a1a1d1f#16be548d-8a8e-80b6-b42c-c841f50ccd04\\">인지부하</a>가 있을 수 있으므로, 사용자에게 좋운 프레임워크를 선택하는 것만이 좋은 길이 아닐 수도 있습니다. 모든 것은 제약사항이 어떤지에 따라 달려있습니다.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80c4-98ba-f1850c700ba1\\" id=\\"235e548d-8a8e-80c4-98ba-f1850c700ba1\\">마이그레이션은 언제나 힘들다.</h2><a href=\\"https://craft.faire.com/the-worlds-longest-react-hooks-migration-8f357cdcdbe9\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://craft.faire.com/the-worlds-longest-react-hooks-migration-8f357cdcdbe9</a><p data-notion-block-id=\\"235e548d-8a8e-8076-838b-d783b6397df1\\">2022년부터 지금까지, MobX와 클래스 컴포넌트가 어떤 문제를 갖고 있었는지, 그리고 어떤 마이그레이션 전략을 짰는지, 어떤 것이 병목이 되었는지까지 소개하는 글입니다. 결국, 조직적으로 공통된 믿음과 설득이 필요함을 보여주는 글입니다.</p><h1 data-notion-block-id=\\"232e548d-8a8e-8065-80bf-e6b08333801c\\">Straight to the Article: 빛나는 인사이트</h1><h2 data-notion-block-id=\\"235e548d-8a8e-8059-8af8-debe5d7d567d\\" id=\\"235e548d-8a8e-8059-8af8-debe5d7d567d\\">nvm을 사용하지 않는 것은 의외로 개발에 도움이 된다</h2><a href=\\"https://nodevibe.substack.com/p/the-500x-performance-gap-between\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nodevibe.substack.com/p/the-500x-performance-gap-between</a><p data-notion-block-id=\\"235e548d-8a8e-80f6-89ba-caa7dd329cae\\">shell에서 warm start와 cold start가 어떻게 작동하는지, 그리고 nvm과 fnm/volta는 어떻게 다른지 소개하는 글입니다. 그리고 nvm 대신 fnm/volta를 사용하면 얼마나 개발 시간을 아낄 수 있는지 벤치마크로 보여주는 글입니다.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80a1-a027-e6c9e1626eb0\\" id=\\"235e548d-8a8e-80a1-a027-e6c9e1626eb0\\"><code>Promise.all</code>, 잘 쓰기 위한 타입과 함수</h2><a href=\\"https://spin.atomicobject.com/better-promise-all/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://spin.atomicobject.com/better-promise-all/</a><p data-notion-block-id=\\"235e548d-8a8e-80fd-97ae-d0a1a488e496\\"><code>Promise.all</code>(<code>Promise.allSettled</code>)을 더 잘 쓰기 위해 utility type과 function을 소개하는 글입니다.</p><h2 data-notion-block-id=\\"232e548d-8a8e-80ec-8d78-f81601882db0\\" id=\\"232e548d-8a8e-80ec-8d78-f81601882db0\\">WASM은 어디에 쓰는거죠?</h2><a href=\\"https://queue.acm.org/detail.cfm?id=3746171\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://queue.acm.org/detail.cfm?id=3746171</a><p data-notion-block-id=\\"235e548d-8a8e-8010-8efa-f6c203f83fa1\\">WASM에 대한 간단한 이해와 WASM의 웹, 웹이 아닌 곳에서의 성공사례를 살펴보면서, 현재 각 분야에서의 WASM이 어떤 상황에 있고, 어떤 미래로 흘러갈 것인지 소개하는 글입니다.</p><h2 data-notion-block-id=\\"235e548d-8a8e-80ee-9c01-cb1709972944\\" id=\\"235e548d-8a8e-80ee-9c01-cb1709972944\\">쿼리빌더 비교하기</h2><a href=\\"https://marmelab.com/blog/2025/06/26/kysely-vs-drizzle.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marmelab.com/blog/2025/06/26/kysely-vs-drizzle.html</a><p data-notion-block-id=\\"232e548d-8a8e-80d2-81c6-f40b31c1fc59\\">Typescript 기반 쿼리 빌더 두 가지(Kysely, Drizzle)를 비교해가면서 어떤 것이 어떤 측면에서 좋은지 비교하는 글입니다.</p><h2 data-notion-block-id=\\"232e548d-8a8e-8058-b934-f4ca0c39f9e9\\" id=\\"232e548d-8a8e-8058-b934-f4ca0c39f9e9\\">Module Federation 알아보기</h2><a href=\\"https://developersvoice.com/blog/frontend/micro-frontends-with-react-and-angular/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developersvoice.com/blog/frontend/micro-frontends-with-react-and-angular/</a><p data-notion-block-id=\\"235e548d-8a8e-80d5-b8f5-d434855726e2\\">Micro frontend를 선택할 때 Module Federation이 왜 좋은 선택지인지, 그리고 실제 상황에서는 어떻게 해야하는지 소개하는 글입니다.</p><h2 data-notion-block-id=\\"235e548d-8a8e-8017-b46f-e6a67654307f\\" id=\\"235e548d-8a8e-8017-b46f-e6a67654307f\\">tabindex 잘 사용하는 방법</h2><a href=\\"https://blog.pope.tech/2025/07/01/tabindex-what-it-is-how-it-works-and-when-to-use-it/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.pope.tech/2025/07/01/tabindex-what-it-is-how-it-works-and-when-to-use-it/</a><h1 data-notion-block-id=\\"232e548d-8a8e-80af-b3bb-ee54559306ee\\">Fresh Finds: 놓치지 말아야 할 소식</h1><a href=\\"https://nextjs.org/blog/next-15-4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/next-15-4</a><p data-notion-block-id=\\"232e548d-8a8e-806f-adb8-f9769dbfb039\\">안정성을 위한 Next.js 15.4 소식이 Next.js 16이 어떻게 될지에 대한 소식입니다.</p><a href=\\"https://nuxt.com/blog/v4\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nuxt.com/blog/v4</a><p data-notion-block-id=\\"235e548d-8a8e-80cd-b9bd-dc315b3414cf\\">새로운 디렉토리 구조, 데이터 fetching 방식, DX가 좋아진 Nuxt 4.0가 배포되었다는 소식입니다.</p><a href=\\"https://remix.run/blog/react-router-and-react-server-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://remix.run/blog/react-router-and-react-server-components</a><p data-notion-block-id=\\"232e548d-8a8e-8014-8207-c09950b19126\\">React Router에서 RSC 지원이 베타로 시작되었다는 소식은 드렸지만, 그 미래는 어떻게 될 것인지를 소개되지 않아서, 그 미래를 소개하는  글입니다.</p><a href=\\"https://hyperfetch.bettertyped.com/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://hyperfetch.bettertyped.com/</a><p data-notion-block-id=\\"232e548d-8a8e-8086-a5de-fe5b0385d722\\">Tanstack Query처럼 서버 상태를 가져오는 역할을 하지만, 하지만 다른 접근 방식으로 만들어진 라이브러리인 Hyperfetch입니다. 더 복잡하고 자세하게 관리하는데에 좋은 역할을 할 것으로 보입니다.</p><a href=\\"https://github.com/colinhacks/zshy\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/colinhacks/zshy</a><p data-notion-block-id=\\"235e548d-8a8e-8013-8a53-e79baaa8429b\\">번들러 없이 TypeScript 컴파일러 API를 기반으로 빌드해주는 빌드 툴입니다.</p><h2 data-notion-block-id=\\"239e548d-8a8e-8059-83ba-df566e725086\\" id=\\"239e548d-8a8e-8059-83ba-df566e725086\\">번외: AI는 정말 생산성을 가져오는가</h2><a href=\\"https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://metr.org/blog/2025-07-10-early-2025-ai-experienced-os-dev-study/</a><p data-notion-block-id=\\"235e548d-8a8e-8056-9f7a-f94db8151caf\\">오픈소스 개발자가 경험한 AI의 생산성은 낮아졌다는 통계입니다. AI로 인한 생산성 향상이 거짓이 아닌가는 종합해서 고려해봐야 한다는 교훈을 남기는 글입니다.</p>"},"relativePath":"news/post/232e548d-8a8e-80b9-9a03-c5b9f894fa41.md","filePath":"news/post/[id].md"}'),o={name:"news/post/232e548d-8a8e-80b9-9a03-c5b9f894fa41.md"};function r(d,c,n,l,i,b){return a(),t("div")}const h=e(o,[["render",r]]);export{f as __pageData,h as default};
